sys_script_include.script:
var PrefillCatalogItemUtils = Class.create();
PrefillCatalogItemUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getPreviousRequestInfo: function() {
		var aaaId = this.getParameter('sysparm_paraId');
		var result = {};
		var mtomGR = new GlideRecord('sc_item_option_mtom');
		mtomGR.addQuery('request_item', aaaId);
		gs.error('varibles0002432432:');
		mtomGR.query();
		gs.error('varibles1111:' + mtomGR);
		while(mtomGR.next()) {
			var optionGR = new GlideRecord('sc_item_option');
			optionGR.get(mtomGR.sc_item_option);
			gs.error('varibles1112:' + optionGR.value);
			gs.error('varibles1112name:' + optionGR.item_option_new.name);
			result[optionGR.item_option_new.name+''] = optionGR.value+'';
		}
		var jsson = new global.JSON().encode(result);
		gs.error('json:' + jsson);
		return jsson;
	},
    type: 'PrefillCatalogItemUtils'
});
